// MIPS 5-Stage Pipeline Conceptual Flow
// Optimal throughput: 1 instruction per clock cycle (IPC=1)
I1: Fetch | Decode | Execute | Memory | WriteBack
I2:       | Fetch | Decode | Execute | Memory | WriteBack
I3:       |       | Fetch | Decode | Execute | Memory | WriteBack

// Data Hazard (Read After Write - RAW)
// I2 needs R1 before I1 writes it back (WB)
ADD R1, R2, R3    // R1 written (Cycle 5)
SUB R4, R1, R5    // R1 read (Cycle 3)

// Hazard Solution: Forwarding (Bypassing)
// Result of I1's EX stage feeds directly into I2's EX stage input
I1: ... | EX(R1=X) | MEM | WB
I2: ... | ID(Read R1) | EX(Uses X) | MEM | WB

// Control Hazard Mitigation
// Branch Prediction (Predict Taken/Not Taken)
if (R1 == R2) {
    JUMP target;
}
// Misprediction penalty = Pipeline flush (N cycles)

// Instruction-Level Parallelism (Superscalar Execution)
// Dispatching multiple independent instructions simultaneously (IPC > 1)
// Cycle 1: Dispatch I1 (ALU) & I2 (LSU)
I1: ADD R1, R2, R3  // Functional Unit A
I2: LW  R4, 8(R5)   // Functional Unit B
